import { useEffect, useState } from "react";

import { upiIntent } from "../../services/paymentService";
import { useNotification } from "../../context/NotificationContext";
import Button from "../common/Button";
import UpiReferenceModal from "./UpiReferenceModal";
import { formatMoney } from "../../utils/format";

/**
 * "Pay by UPI" box - one component, two jobs.
 *
 * 1. **Show how to pay.** The store's QR (uploaded or generated by an admin in
 *    Settings -> UPI), the UPI ID with a copy button, the payee name, the amount
 *    and the order number to use as the transaction note. On a phone the
 *    "Open in UPI app" button deep-links straight into GPay / PhonePe / Paytm.
 *
 * 2. **Take the confirmation**, but only when a `paymentId` is supplied (i.e.
 *    after the order exists). The customer types the UPI reference they can see
 *    in their UPI app and, optionally, attaches the payment screenshot. The API
 *    then puts the payment in front of an admin for approval.
 *
 * Status banners keep the customer oriented: awaiting payment -> under review ->
 * approved, or rejected with the admin's reason and the form reopened.
 */

const STATUS_BANNER = {
  awaiting_verification: {
    tone: "amber",
    title: "Waiting for your UPI payment",
    body: "Scan the QR or pay to the UPI ID, then confirm below with the reference number from your UPI app.",
  },
  pending: {
    tone: "sky",
    title: "Payment submitted — under review",
    body: "We have your reference. The store verifies it against the bank statement, usually within a few minutes.",
  },
  pending_verification: {
    tone: "sky",
    title: "Payment submitted — under review",
    body: "We have your reference. The store verifies it against the bank statement, usually within a few minutes.",
  },
  paid: {
    tone: "brand",
    title: "Payment received",
    body: "Thanks — this order is paid.",
  },
  approved: {
    tone: "brand",
    title: "Payment received",
    body: "Thanks — this order is paid.",
  },
  rejected: {
    tone: "rose",
    title: "We could not match that payment",
    body: "Check the reference number and submit again, or pay cash on delivery.",
  },
};

const TONES = {
  amber: "border-amber-200 bg-amber-50 text-amber-900",
  sky: "border-sky-200 bg-sky-50 text-sky-900",
  brand: "border-brand-200 bg-brand-50 text-brand-900",
  rose: "border-rose-200 bg-rose-50 text-rose-900",
};

export default function UpiPayBox({
  upiId,
  payeeName,
  qrUrl,
  amount,
  note,
  help,
  paymentId = null,
  paymentStatus = null,
  rejectionReason = "",
  canSubmit = true,
  /*
   * The order page shows the QR for reference but no "I have paid - enter
   * transaction ID" button: the reference is given before the order is placed,
   * so there is nothing left to ask for there.
   */
  showResubmit = true,
  autoOpen = false,
  onSubmitted,
  compact = false,
}) {
  const { notify } = useNotification();
  const [copied, setCopied] = useState(false);
  const [confirmOpen, setConfirmOpen] = useState(false);

  /*
   * The reference popup.
   *
   * `autoOpen` is set by the order page the first time a UPI order is opened with
   * nothing submitted yet: the customer has just come back from their UPI app, so
   * asking for the transaction ID right there is the whole point of the screen.
   * Every later visit uses the button instead, so it never nags twice.
   */
  useEffect(() => {
    if (autoOpen && paymentId && canSubmit) setConfirmOpen(true);
  }, [autoOpen, paymentId, canSubmit]);

  const intent = upiIntent({ upiId, payeeName, amount, note });
  const banner = STATUS_BANNER[paymentStatus] || null;

  const copyUpiId = async () => {
    try {
      await navigator.clipboard.writeText(upiId);
      setCopied(true);
      setTimeout(() => setCopied(false), 1800);
    } catch {
      notify.error("Could not copy — please type the UPI ID manually.");
    }
  };

  return (
    <div className="overflow-hidden rounded-2xl border border-slate-200 bg-white">
      <div className="flex items-center gap-2 border-b border-slate-100 bg-slate-50/70 px-4 py-3">
        <span className="grid h-7 w-7 place-items-center rounded-lg bg-brand-600 text-white">
          <svg viewBox="0 0 24 24" className="h-4 w-4" fill="none" stroke="currentColor" strokeWidth="2">
            <rect x="3" y="3" width="7" height="7" rx="1" />
            <rect x="14" y="3" width="7" height="7" rx="1" />
            <rect x="3" y="14" width="7" height="7" rx="1" />
            <path d="M14 14h3v3h-3zM20 14h1M14 20h1M18 18h3v3" />
          </svg>
        </span>
        <div>
          <p className="text-sm font-bold text-slate-900">Pay by UPI</p>
          <p className="text-[11px] text-slate-500">
            GPay · PhonePe · Paytm · any bank app
          </p>
        </div>
      </div>

      {banner ? (
        <div className={`mx-4 mt-4 rounded-xl border px-3 py-2.5 ${toneClasses(banner.tone)}`}>
          <p className="text-xs font-bold">{banner.title}</p>
          <p className="mt-0.5 text-[11px] leading-relaxed opacity-90">{banner.body}</p>
          {paymentStatus === "rejected" && rejectionReason ? (
            <p className="mt-1 text-[11px] font-semibold">Reason: {rejectionReason}</p>
          ) : null}
        </div>
      ) : null}

      <div className={`grid gap-4 p-4 ${compact ? "" : "sm:grid-cols-[168px_1fr]"}`}>
        {/* QR */}
        <div className="mx-auto w-fit">
          <div className="grid h-[168px] w-[168px] place-items-center overflow-hidden rounded-xl border border-slate-200 bg-white p-2">
            {qrUrl ? (
              <img src={qrUrl} alt={`UPI QR code for ${upiId}`} className="h-full w-full object-contain" />
            ) : (
              <div className="px-3 text-center">
                <p className="text-[11px] font-semibold text-slate-500">QR not uploaded yet</p>
                <p className="mt-1 text-[10px] text-slate-400">
                  Pay to the UPI ID below instead.
                </p>
              </div>
            )}
          </div>
          <p className="mt-1.5 text-center text-[10px] uppercase tracking-wide text-slate-400">
            Scan with any UPI app
          </p>
        </div>

        {/* ID + amount */}
        <div className="min-w-0 space-y-2.5">
          <div>
            <p className="text-[10px] font-bold uppercase tracking-wide text-slate-500">UPI ID</p>
            <div className="mt-1 flex items-center gap-2">
              <code className="min-w-0 flex-1 truncate rounded-lg bg-slate-100 px-2.5 py-1.5 text-sm font-bold text-slate-900">
                {upiId || "Not configured"}
              </code>
              <Button size="sm" variant="secondary" onClick={copyUpiId} disabled={!upiId}>
                {copied ? "Copied" : "Copy"}
              </Button>
            </div>
          </div>

          <dl className="grid grid-cols-2 gap-2 text-xs">
            <div>
              <dt className="text-slate-500">Payee</dt>
              <dd className="font-semibold text-slate-900">{payeeName || "—"}</dd>
            </div>
            <div>
              <dt className="text-slate-500">Amount</dt>
              <dd className="font-extrabold tabular-nums text-slate-900">
                {amount !== undefined && amount !== null ? formatMoney(amount) : "—"}
              </dd>
            </div>
            {note ? (
              <div className="col-span-2">
                <dt className="text-slate-500">Transaction note</dt>
                <dd className="font-semibold text-slate-900">{note}</dd>
              </div>
            ) : null}
          </dl>

          {intent ? (
            <a
              href={intent}
              className="inline-flex w-full items-center justify-center gap-1.5 rounded-lg border border-brand-200 bg-brand-50 px-3 py-2 text-xs font-bold text-brand-800 hover:bg-brand-100 sm:w-auto"
            >
              Open in UPI app
              <span aria-hidden="true">↗</span>
            </a>
          ) : null}

          {help ? (
            <p className="rounded-lg bg-amber-50 px-2.5 py-2 text-[11px] font-medium text-amber-800">
              {help}
            </p>
          ) : null}
        </div>
      </div>

      {/* Confirmation: a button that opens the "paste your transaction ID" popup. */}
      {showResubmit && paymentId && canSubmit ? (
        <div className="border-t border-slate-100 bg-slate-50/60 p-4">
          <p className="text-xs font-bold text-slate-900">Already paid?</p>
          <p className="mt-0.5 text-[11px] text-slate-500">
            Paste the transaction ID / UTR from your UPI app so the store can match your payment.
          </p>
          <Button type="button" className="mt-3" onClick={() => setConfirmOpen(true)}>
            {paymentStatus === "rejected" ? "Try again with a new transaction ID" : "I have paid — enter transaction ID"}
          </Button>
        </div>
      ) : null}

      <UpiReferenceModal
        open={confirmOpen}
        onClose={() => setConfirmOpen(false)}
        paymentId={paymentId}
        amount={amount}
        orderNumber={note}
        upiId={upiId}
        payeeName={payeeName}
        qrUrl={qrUrl}
        onSubmitted={onSubmitted}
      />

      {showResubmit && paymentId && !canSubmit ? (
        <div className="border-t border-slate-100 bg-slate-50/60 px-4 py-3">
          <p className="text-[11px] font-medium text-slate-600">
            No further action needed — this payment is settled.
          </p>
        </div>
      ) : null}
    </div>
  );
}

/** Guard against a mis-keyed tone ever producing `undefined` classes. */
function toneClasses(tone) {
  return TONES[tone] || TONES.sky;
}
